const PLACES = [
  {
    id:'flatiron', name:'Flatiron Building', neighborhood:'Flatiron', address:'175 Fifth Avenue', year:'1902', style:'A skyscraper shaped by its street', lat:40.74106, lng:-73.98970, tags:['Film & TV','Architecture'], time:8,
    lookUp:'Stand at the narrow tip on 23rd Street and look all the way up: the top floors flare out into a heavy, carved crown, like the brim of a very serious hat.',lookUpCrop:{x:44,y:10,r:16},
    teaser:'A slice of New York. A superhero’s day job.', hook:'You know the silhouette. Here’s the story.',
    story:'That impossibly narrow point is the result of Broadway cutting across Fifth Avenue. Daniel Burnham’s building fits its triangular plot like a ship’s bow. When it opened in 1902, its unusual shape drew plenty of skepticism. Today, it is one of the city’s most recognizable faces.',
    looks:['Stand in the pedestrian area north of 23rd Street to see the narrow tip.','Follow the rows of windows around the corner: the building suddenly seems much wider.','Look for the richly decorated top above the long, repeating middle.'],
    culture:[{type:'On screen · exterior',title:'Spider-Man (2002)',text:'Peter Parker’s workplace has a real New York address: the Flatiron’s exterior stands in for the fictional Daily Bugle. You’re looking at a movie newspaper office, not the home of an actual Daily Bugle.'}],
    tip:'Enjoy this stop from the public sidewalk or pedestrian plaza. Interior access is not part of the walk.',
    sources:[['Flatiron NoMad · building history','https://flatironnomad.nyc/history/the-flatiron-building/'],['Flatiron NoMad · film connections','https://flatironnomad.nyc/history/film-television-in-the-district/']]
  },
  {
    id:'nypl', name:'New York Public Library', neighborhood:'Midtown', address:'476 Fifth Avenue', year:'1911', style:'A palace for public knowledge', lat:40.75318,lng:-73.98225,tags:['Film & TV','Books','Architecture'],time:12,
    lookUp:'Look up past the lions and over the columns: a row of stone figures stands along the top of the façade, keeping watch over Fifth Avenue.',lookUpCrop:{x:50,y:27,r:22},
    teaser:'Two stone lions. Millions of stories. A familiar ghost.',hook:'The grandest invitation to pick up a book.',
    story:'The Stephen A. Schwarzman Building turns a public library into a civic palace. Its broad steps, enormous windows, and marble entrance make reading feel like an occasion. You can enjoy the building’s exterior on a quick walk, or check the library’s visitor information to explore inside.',
    looks:['Meet the two stone lions on either side of the Fifth Avenue steps.','Notice how the three tall entrance arches make a busy street feel ceremonial.','Step back on the sidewalk and follow the building’s long, balanced façade.'],
    culture:[{type:'On screen · filming location',title:'Ghostbusters (1984)',text:'The library appears in the film’s opening encounter with a ghost. Recognize the exterior, but remember that a movie’s interiors and exteriors can come from different places.'},{type:'On screen · filming location',title:'Breakfast at Tiffany’s (1961)',text:'Holly and Paul’s day in the city includes a visit to this library. It is one of several real New York places woven into the film.'}],
    tip:'The exterior is an easy walking stop. Reading-room access and tours have their own rules; check the library before planning an indoor visit.',
    sources:[['NYPL · visiting the Schwarzman Building','https://www.nypl.org/locations/schwarzman'],['NYPL · movies filmed at the library','https://www.nypl.org/press/popular-movies-filmed-new-york-public-library']]
  },
  {
    id:'grandcentral',name:'Grand Central Terminal',neighborhood:'Midtown',address:'89 East 42nd Street',year:'1913',style:'A station with a sky of its own',lat:40.75273,lng:-73.97723,tags:['Architecture','Hidden gems'],time:15,
    lookUp:'On 42nd Street, look above the tall center window: Mercury, with Hercules and Minerva at his sides, stands guard over a clock made of Tiffany glass.',lookUpCrop:{x:68,y:33,r:11},
    teaser:'A little wonder, even when you’re running for a train.',hook:'Give your commute a five-minute detour.',
    story:'Grand Central was built to make arriving in New York feel extraordinary. Above the busy Main Concourse, a turquoise ceiling opens onto a painted sky. The information-booth clock offers a meeting point below it. Even a familiar commute can become a small architectural adventure if you pause and look up.',
    looks:['From a clear spot in the Main Concourse, look up at the painted constellations.','Find the four-faced clock above the information booth.','By the Oyster Bar on the lower level, the vaulted Whispering Gallery carries sound between opposite corners. Try it with a friend without blocking the passage.'],
    culture:[{type:'City life · a small ritual',title:'Meet me under the clock',text:'A train terminal can also be a shared living room. Watch the arrivals, reunions, and commuters circling its central information booth.'}],
    tip:'This is a working terminal. Keep paths clear and follow posted access information. Indoor stops depend on current access.',
    sources:[['Grand Central Terminal · what to see','https://m.grandcentralterminal.com/what-to-see/'],['Grand Central Terminal · history','https://m.grandcentralterminal.com/history/']]
  },
  {
    id:'plaza',name:'The Plaza',neighborhood:'Central Park South',address:'768 Fifth Avenue',year:'1907',style:'A hotel with a storybook life',lat:40.76450,lng:-73.97436,tags:['Film & TV','Books','Architecture'],time:8,
    lookUp:'Look up to the green copper roof: steep gables, turrets, and dormers, as if a French château decided to grow 19 stories.',lookUpCrop:{x:36,y:21,r:12},
    teaser:'Kevin’s New York adventure. Eloise’s entire world.',hook:'Some of its most famous guests are fictional.',
    story:'At the corner of Fifth Avenue and Central Park South, the Plaza’s pale façade and steep roof turn a hotel into a landmark. Its reputation lives as much in stories as in its guest rooms: for generations of readers and moviegoers, this is where a New York adventure begins.',
    looks:['View the steep roof and ornate upper floors from the public space across Fifth Avenue.','Compare the grand hotel entrance with the park directly across the street.','Notice how the building’s corner anchors the meeting of avenue and park.'],
    culture:[{type:'On the page · fictional setting',title:'Eloise',text:'Kay Thompson’s mischievous six-year-old, illustrated by Hilary Knight, makes the Plaza her home. The hotel is the setting of her fictional adventures.'},{type:'On screen · filming location',title:'Home Alone 2 (1992)',text:'Kevin McCallister checks in to the Plaza in the film. The hotel’s own history records filming in its 59th Street lobby.'}],
    tip:'This stop works from public outdoor space. Hotel interiors, dining, and experiences may require reservations or have access restrictions.',
    sources:[['The Plaza · faces, films, and moments','https://www.theplazany.com/history/faces-films-moments/'],['The Plaza · historical timeline','https://www.theplazany.com/history/timeline-history-of-the-plaza-hotel/']]
  },
  {
    id:'jefferson',name:'Jefferson Market Library',neighborhood:'Greenwich Village',address:'425 Sixth Avenue',year:'1877',style:'A courthouse with a second chapter',lat:40.73469,lng:-73.99958,tags:['Books','Hidden gems','Architecture'],time:10,
    lookUp:'Follow the brick tower up to the clock faces near the top. This was once a fire lookout, back when spotting smoke was a job.',lookUpCrop:{x:54,y:23,r:11},
    teaser:'It looks like a castle. It used to be a courthouse.',hook:'A neighborhood helped this building begin again.',
    story:'The clock tower and red brick might suggest a storybook castle. This was actually a courthouse, completed in 1877. When the building faced an uncertain future, neighbors campaigned to save it. It reopened as a library in 1967, giving rooms once used for trials a new life filled with books.',
    looks:['Pick out the clock high in the tower.','Look for pointed arches and the contrasting colors of brick and stone.','Walk around the corner to see how the building fits its irregular site.'],
    culture:[{type:'Neighborhood story · a new life',title:'From courtroom to reading room',text:'Its change of use is part of a larger Village story: residents deciding that a familiar building deserved another chapter. The building’s form survived while its public purpose changed.'}],
    tip:'Enjoy the exterior from Sixth Avenue and West 10th Street. Check branch hours before planning to enter.',
    sources:[['NYPL · Jefferson Market history','https://www.nypl.org/about/locations/jefferson-market'],['NYPL · branch and visitor information','https://www.nypl.org/locations/jefferson-market']]
  },
  {
    id:'washington',name:'Washington Square Arch',neighborhood:'Greenwich Village',address:'Washington Square North at Fifth Avenue',year:'1890s',style:'A gateway to the Village',lat:40.73123,lng:-73.99708,tags:['Books','Hidden gems','Architecture'],time:10,
    lookUp:'Look above the archway: a carved eagle spreads its wings, and above it, Washington’s own words run across the top in capital letters.',lookUpCrop:{x:50,y:37,r:12},
    teaser:'A marble arch, a literary neighborhood, a place to linger.',hook:'The city’s grandest doorway has no door.',
    story:'Stanford White’s temporary arch for the 1889 centennial of Washington’s inauguration was so popular that a permanent marble version followed. Today it frames Fifth Avenue on one side and the life of the park on the other. Its surroundings have welcomed writers, performers, protests, and everyday pauses.',
    looks:['Stand south of the arch and use it to frame Fifth Avenue.','Compare the two sculptures of Washington on its north-facing side.','Turn toward the row houses along Washington Square North to see a very different scale of city.'],
    culture:[{type:'On the page · neighborhood setting',title:'Washington Square · Henry James',text:'James’s novel is connected to the neighborhood around the square. He visited his grandmother’s home on Washington Square North as a child. The literary connection is to the neighborhood, rather than the later arch.'}],
    tip:'An outdoor stop with room to pause in the park. Follow posted park rules and keep paths open.',
    sources:[['Washington Square Park Conservancy · history','https://www.washingtonsqpark.org/history'],['NYC Parks · Washington Square Arch','https://nycgovparks.org/parks/washington-square-park/monuments/1657']]
  },
  {
    id:'haughwout',name:'Haughwout Building',neighborhood:'SoHo',address:'488–492 Broadway',year:'1857',style:'An elegant storefront made of iron',lat:40.72249,lng:-73.99966,tags:['Hidden gems','Architecture'],time:8,
    lookUp:'On the Broadway side, look up to the second floor: a clock is set right into the cast-iron façade, still keeping Broadway on time.',lookUpCrop:{x:26,y:69,r:5},
    teaser:'Luxury shopping helped give the elevator a lift.',hook:'Look past the shop windows. Then look up.',
    story:'This Broadway corner was built for a luxury store selling china, glass, and silver. Its repeated arches and columns were made with cast iron, giving a commercial building the elegance of a grand palace. In 1857, it also introduced customers to an early passenger elevator—an innovation that would help change how cities grew upward.',
    looks:['Follow the repeating arched windows across the Broadway façade.','Turn the corner onto Broome Street to see the pattern continue.','Notice how the upper stories form orderly rows above the storefronts.'],
    culture:[{type:'City life · an everyday invention',title:'Shopping, but upstairs',text:'Before elevators became ordinary, reaching upper floors was part of the challenge of selling goods. Here, a shopping trip offered customers a new way to move through a building.'}],
    tip:'This is an exterior stop on busy sidewalks. The historic elevator is not offered as a visitor attraction.',
    sources:[['Historic Districts Council · Haughwout Building','https://hdc.org/buildings/e-v-haughwout-building/'],['SAH Archipedia · Haughwout Building','https://sah-archipedia.org/buildings/NY-01-061-0008']]
  },
  {
    id:'puck',name:'Puck Building',neighborhood:'SoHo / Nolita',address:'295 Lafayette Street',year:'1886',style:'A red-brick palace for a humor magazine',lat:40.72430,lng:-73.99535,tags:['Film & TV','Hidden gems','Architecture'],time:8,
    lookUp:'At the Houston and Mulberry corner, look up to the third floor: a gilded Puck in a top hat, quill in hand, is ready to mock you personally.',lookUpCrop:{x:10.5,y:65,r:5},
    audio:{src:'assets/audio/puck.mp3',duration:213,chapters:[{title:'Meet Puck',start:0,text:'Face the Houston and Mulberry corner. Look up at the roof line. See the gilded figure in a top hat holding an oversized pen? That’s Puck—not the woodland sprite from Shakespeare, though he borrowed the name and the famous line, “What fools these mortals be.” This Puck is a Victorian dandy, the mascot of a magazine that spent decades poking fun at the powerful. Puck was founded by Joseph Keppler, an Austrian-born cartoonist who started it in German before launching an English edition. His readers were a city full of immigrants, and his color lithographs were a sensation. This entire block was built for the magazine.'},{title:'The brick',start:40.64,text:'Scan the walls at street level, then follow the rows of arched windows upward. Red brick, round arches, a solid, almost fortress-like feel. The architect, Albert Wagner, was German-born, and he drew on a German tradition called Rundbogenstil, meaning “round-arch style.” It’s related to the Romanesque Revival that was fashionable in the 1880s, but it isn’t the heavy, rugged version made famous by H. H. Richardson. Wagner’s is more orderly. Keppler commissioned the building in 1885. The first section went up in 1885 and 1886, and a large addition followed in 1892 and 1893. It wasn’t just offices—it was a working printing plant, shared with the J. Ottmann Lithographing Company, which printed Puck’s color pages.'},{title:'The second Puck',start:90.28,text:'Find the main entrance on Lafayette Street. Look just above the door. There’s a second, smaller gilded Puck here, and this façade isn’t original. When the city pushed Lafayette Street through in the late 1890s, part of the building was shaved off and the front had to be rebuilt. Wagner’s relative, Herman Wagner, oversaw the work, and he matched the original so closely that the building reads as one piece.'},{title:'After the magazine',start:117.64,text:'Look up past the cornice to the rooftop. Puck stopped publishing in 1918, but the building stayed a place for printers and publishers. In the 1980s, it housed Spy magazine, a sharp, satirical monthly that was very much Puck’s spiritual heir. In 1983, the city designated the building a landmark. Later came offices, event space, and—after a long review by the Landmarks Commission—rooftop penthouses, approved in 2011 in a scaled-back form. Notice that the additions sit behind the restored cornice, so from the street, the old silhouette mostly holds.'},{title:'As seen on screen',start:157.6,text:'Step back to the far side of Lafayette Street and take in the whole façade. If this building looks familiar, you’ve probably seen it before. It’s best known as the exterior of Grace Adler’s design studio on Will & Grace. And it’s been linked to other screen appearances, including American Psycho, When Harry Met Sally, and the original Teenage Mutant Ninja Turtles. It’s easy to see why. The red brick, the arched windows, and that gilded figure say “downtown New York” without a word of dialogue. Billy Joel is said to have rented space while working on his album The Bridge. A building made for a magazine of troublemakers has kept attracting people who make things. So when you pass this block, look up. It’s a printing plant, a political joke, a sitcom set, and an immigrant success story—all in brick, with a gilded troublemaker keeping watch.'}]},
    teaser:'A gold-leafed sprite still keeps an eye on Houston Street.',hook:'Find the little gold figure. Then take in the whole block.',
    story:'This red-brick building was made for Puck, a satirical magazine famous for its colorful political cartoons, and the printers who produced it. Albert Wagner designed it in a round-arched Romanesque Revival style, with long rows of arched windows that let daylight into busy workrooms. Puck closed in 1918, but its namesake never left: gilded statues of Shakespeare’s mischievous sprite still stand on the building.',
    looks:['At the corner of Houston and Mulberry Streets, look up for the gilded Puck holding a mirror.','Walk around to Lafayette Street to find a second Puck above the entrance.','Follow the rows of arched windows: tall at the bottom, smaller as they rise.'],
    culture:[{type:'On screen · exterior',title:'Will & Grace (1998–2006, 2017–2020)',text:'The exterior stands in for the building that houses Grace Adler Designs, Grace’s interior design firm. Recognize the outside—the office itself was a TV set.'}],
    tip:'Enjoy this stop from the public sidewalk. The building is home to private residences and businesses.',
    sources:[['NYC Landmarks Preservation Commission · designation report (1983)','https://s-media.nyc.gov/agencies/lpc/lp/1226.pdf'],['IMDb · Will & Grace filming locations','https://www.imdb.com/title/tt0157246/locations/']]
  },
  {
    id:'oldcathedral',name:'St. Patrick’s Old Cathedral',neighborhood:'Nolita',address:'263 Mulberry Street',year:'1815',style:'New York’s first cathedral',lat:40.72385,lng:-73.99470,tags:['Film & TV','Architecture'],time:8,
    lookUp:'Look up at the main front, above the tall pointed window: a small round window sits near the peak of the gable, like a watchful eye.',lookUpCrop:{x:36,y:26,r:9},
    teaser:'You’ve seen this church in The Godfather.',hook:'A quiet churchyard with a famous close-up.',
    story:'Built between 1809 and 1815, this was New York’s Catholic cathedral until the new St. Patrick’s opened on Fifth Avenue in 1879. Its tall brick walls wrap a churchyard that feels far from the busy streets around it. Film lovers know the interior: Francis Ford Coppola chose it for the baptism scene in The Godfather, and the baby in that scene was his daughter, Sofia.',
    looks:['Walk along Mott Street and follow the old brick wall that encloses the churchyard.','Find the entrance on Mott Street, between Houston and Prince Streets.','Look up at the plain stone façade, built when this was still the edge of the city.'],
    culture:[{type:'On screen · interior',title:'The Godfather (1972)',text:'The famous baptism sequence was filmed inside this church. Martin Scorsese, who grew up a few blocks away, also featured it in his New York films.'}],
    tip:'This is an active church. Enjoy the outside from the sidewalk; if you step in, check service times and keep visits quiet and respectful.',
    sources:[['Basilica of St. Patrick’s Old Cathedral','https://oldcathedral.org/'],['Aleteia · the church loved by Italian American directors','https://aleteia.org/2018/04/04/the-new-york-catholic-church-loved-by-italian-american-directors/']]
  },
  {
    id:'germania',name:'Former Germania Bank',neighborhood:'Bowery',address:'190 Bowery',year:'1899',style:'A granite bank that became a home',lat:40.72145,lng:-73.99365,tags:['Hidden gems','Architecture','Film & TV'],time:7,
    lookUp:'Tip your head all the way back: a crown of green copper trims the roofline of this very serious granite bank.',lookUpCrop:{x:55,y:6,r:16},
    audio:{src:'assets/audio/germania.mp3',duration:226.77,chapters:[{title:'A bank for Little Germany',start:0,text:'Stand across the Bowery at Spring Street and look at the angled corner entrance. This is the Germania Bank Building, built in 1898 and 1899. The bank was founded in 1869 by local businessmen of German descent, and the name says it all. In the mid-1800s, this neighborhood was one of the largest German communities in America. People called it Kleindeutschland, or Little Germany. The bank grew with it, moving between several buildings on the Bowery until it built this one, its third home, right on the corner.'},{title:'Granite and arches',start:39.44,text:'Look at the tall arched windows at street level, then follow the stone up. The architect was Robert Maynicke, who was born in Germany. He designed a six-story building in a Renaissance-inspired style, built of brick on a steel frame and covered in Maine granite on the two street sides. Look at the base. Those big blocks of stone with deep grooves between them give it a heavy, solid look. Architects call that rustication, and it was a way to signal strength and security—exactly what you’d want in a bank.'},{title:'The corner door',start:76.6,text:'Find the angled corner entrance. Look for the columns, the steps, and the iron gates. The main entrance is tucked into the angled corner. It’s framed by freestanding columns in the Tuscan style, a plain, simple version of the Roman column. A short flight of bluestone steps leads up to wrought-iron gates. This corner doorway was built to be seen from two streets at once. A second entrance with similar columns and gates faces the Bowery.'},{title:'A bank changes its name',start:109.44,text:'Look up at the cornice, the heavy ledge at the roofline. Up top, a heavy cornice and a copper parapet crowned the building, with a second, similar cornice marking the fifth floor. The bank itself didn’t stay German for long. In early 1918, during the First World War, it was renamed Commonwealth Bank. It was later taken over by Manufacturers Trust and then merged into Manufacturers Hanover, which kept a branch here until the mid-1960s.'},{title:'A very different kind of home',start:142.4,text:'Look up at the upper floors and picture people living and working behind those windows. In 1966, a photographer named Jay Maisel bought the empty bank building. He didn’t convert it. He moved in. He lived here, worked here, and kept a gallery inside. He also rented space to other artists: the painters Adolph Gottlieb and Roy Lichtenstein both rented floors for a couple of years in the late 1960s. Over the decades, parts of the old bank were turned into living space, and the former banking hall even held a basketball court.'},{title:'Landmark and today',start:181.36,text:'Look at the ground-floor windows and doors, then step back and take in the whole building. In 2005, the city designated the building a landmark, over the owner’s objection. At the hearing, the owner argued that maintaining a landmark would be a financial burden. The commission replied that designation tends to raise a building’s value. The building sold in 2015, and since then it has been put to commercial use, including a retail store and shared offices. So when you pass this corner, look up at the granite. It was a bank for a German neighborhood, a home for an artist, and now a landmark with a very different life ahead.'}]},
        teaser:'Someone turned this enormous bank into a home.',hook:'Imagine living inside a bank vault’s neighborhood.',
    story:'Robert Maynicke designed this granite bank for the Germania Bank in 1898–99, when the Bowery was home to many German immigrants. In 1966, photographer Jay Maisel bought the whole building for $102,000 and spent nearly 50 years living and working in its dozens of rooms. Its graffiti-covered doors became a downtown landmark of their own. Maisel sold it in 2015 for $55 million.',
    looks:['Stand at the corner of Bowery and Spring Street to take in the rounded corner and heavy granite walls.','Look up to the green copper cornice and the row of arched windows just below it.','Notice the tall arched windows that once lit the banking hall.'],
    culture:[{type:'On screen · documentary',title:'Jay Myself (2018)',text:'This documentary follows Jay Maisel as he packs up nearly five decades of art and life and moves out of the bank.'}],
    tip:'This is a private building. Enjoy it from the sidewalk at Bowery and Spring Street.',
    sources:[['Germania Bank Building · Wikipedia','https://en.wikipedia.org/wiki/Germania_Bank_Building_(New_York_City)'],['Artnet · the $55 million sale','https://news.artnet.com/art-world/aby-rosen-pays-55-million-for-gilded-age-building-artist-jay-maisel-bought-for-102000-around-1966-246924']]
  },
  {
    id:'bayard',name:'Bayard–Condict Building',neighborhood:'NoHo',address:'65 Bleecker Street',year:'1899',style:'Louis Sullivan’s only New York building',lat:40.72628,lng:-73.99536,tags:['Hidden gems','Architecture'],time:8,
    lookUp:'Look all the way up to the top floor: winged figures stretch their arms beneath the cornice, between the arches.',lookUpCrop:{x:57,y:14,r:12},
    teaser:'Look up—there are winged figures watching over the street.',hook:'Find the angels. Then find the lace.',
    story:'Chicago architect Louis Sullivan, the mentor of Frank Lloyd Wright, designed only one building in New York, and this is it. Working with Lyndon P. Smith, he wrapped a steel frame in white terra-cotta, with slender piers that pull your eye straight up. At the very top, six winged figures stretch beneath the cornice. Sullivan reportedly didn’t want them; the client, Silas Alden Condict, insisted.',
    looks:['Stand at the top of Crosby Street to see the whole façade end to end.','Look all the way up for the six winged figures under the cornice.','Follow the thin piers and the lace-like terra-cotta ornament between the windows.'],
    culture:[{type:'Architecture · a detail challenge',title:'Spot the angels',text:'Can you find all six? Each one spreads its wings beneath the roofline. The building’s original storefront capitals were removed in 1964; six of them are now at the Brooklyn Museum.'}],
    tip:'Bleecker Street is narrow and busy. The best view is from the corner of Crosby Street.',
    sources:[['Bayard–Condict Building · Wikipedia','https://en.wikipedia.org/wiki/Bayard%E2%80%93Condict_Building'],['Brooklyn Museum · a capital from the building','https://www.brooklynmuseum.org/objects/86919']]
  },
  {
    id:'basquiat',name:'Basquiat’s Studio',neighborhood:'NoHo',address:'57 Great Jones Street',year:'1983',style:'Where a major artist lived and worked',lat:40.72693,lng:-73.99285,tags:['Hidden gems'],time:6,
    lookUp:'Look up to the big arched window on the second floor. Behind it was Basquiat’s studio.',lookUpCrop:{x:40,y:25,r:17},
    audio:{src:'assets/audio/basquiat.mp3',duration:203.55,chapters:[{title:'A small building with a big past',start:0,text:'Cross to the opposite side of Great Jones Street and look at the second floor. This is easy to walk past: two stories of brick tucked between taller neighbors in NoHo. But the story of this address runs from clay chimney pots to one of the most famous artist studios in New York. Long before the building you see now, a mason named James Kinsey was making chimney pots and clay ornaments on this site in the 1840s. The brick building standing today is generally dated to around 1900, though surprisingly little is documented about who built it or why.'},{title:'The façade',start:38.14,text:'Find the large arched window in the center of the second floor. The style is Romanesque Revival, the same round-arch language you might remember from the Puck Building. Look at the three second-floor windows. The big central one has a round arch with a stone keystone at the top, and two smaller windows flank it with similar arches. Down at street level, things look different. Over the decades, the ground floor has been altered, with the central windows replaced by large panes of plate glass. The upper floor is where the original character survives.'},{title:'Rougher days',start:73.12,text:'Look at the entrance, then up to the cornice. The building has had a rougher past, too. In the early 1900s, it was reportedly the headquarters of the Paul Kelly Association, linked to the Five Points Gang, and a 1905 gunfight nearby left a bystander dead. Great Jones Street was a very different place then, closer to a working-class industrial neighborhood than the gallery district it would later become.'},{title:'Warhol and Basquiat',start:100.5,text:'Look at the second-floor windows. This was the studio. By the 1970s, Andy Warhol owned the building. In 1983, a young painter named Jean-Michel Basquiat began renting the second floor from him. The two were close friends, and Basquiat lived and worked up there until 1988. Those were the years of his most celebrated work, made in this one building. He was in his early twenties, already famous, and painting at an extraordinary pace. He died here in 1988, at just 27.'},{title:'A street memorial',start:135.66,text:'Look at the façade for the plaque, then walk toward the Bowery and look up at the corner street sign. After his death, the façade became an informal memorial, covered over time in tributes and graffiti. In 2016, Village Preservation installed a plaque on the building to mark its significance. Walk toward the Bowery and look up at the street sign on the corner. In October 2025, the city and the Basquiat estate officially co-named this stretch Jean-Michel Basquiat Way.'},{title:'Today',start:167.6,text:'Look through the glass at the ground floor and up at the studio level. In 2023, the building began a new chapter when Angelina Jolie rented it and opened Atelier Jolie, a space for design, art, and craft. Reports at the time said the second floor’s Basquiat-era traces, including early comics and graffiti by his collaborator Al Diaz, would be preserved. So when you pass this block, look up at that second floor. A brick workshop became a studio, a studio became a memorial, and the street itself now carries his name.'}]},
        teaser:'Behind this small façade, a major artist lived and worked.',hook:'A small building with a very big story.',
    story:'Jean-Michel Basquiat rented this building from his friend Andy Warhol in 1983. He lived and painted here, in the middle of downtown’s art scene, until his death in 1988 at age 27. Warhol and Basquiat even made paintings together in these years. From the street it’s easy to miss—which makes it all the more remarkable.',
    looks:['Find number 57 on the south side of Great Jones Street, between Lafayette Street and the Bowery.','Notice how modest the façade is compared with the buildings around it.','Look along the block and imagine 1980s downtown, when artists filled these lofts.'],
    culture:[{type:'Art · downtown in the 1980s',title:'Basquiat and Warhol',text:'Warhol owned the building and rented it to Basquiat. The two became friends and collaborators, painting side by side on dozens of canvases.'}],
    tip:'This is a private building. Please view it from the sidewalk and don’t block the doorway.',
    sources:[['Artnet · Basquiat’s home gets a plaque','https://news.artnet.com/art-world/jean-michel-basquiat-gets-noho-plaque-531317'],['Village Preservation','https://www.villagepreservation.org/']]
  },
  {
    id:'publictheater',name:'The Public Theater',neighborhood:'NoHo',address:'425 Lafayette Street',year:'1854',style:'A library that became a stage',lat:40.72913,lng:-73.99185,tags:['Books','Architecture','Film & TV'],time:10,
    lookUp:'Look up to the roofline: stone urns line the parapet, above three floors of round-arched windows that once lit the Astor Library’s reading rooms.',lookUpCrop:{x:38,y:14,r:9},
    audio:{src:'assets/audio/publictheater.mp3',duration:218.67,chapters:[{title:'The Astor Library',start:0,text:'Stand across Lafayette Street and take in the whole façade. Before this was a theater, it was a library—and not just any library. The Astor Library was one of the first large public libraries in New York, paid for with money from John Jacob Astor. The cornerstone was laid in 1850, and it opened to readers in 1854. It wasn’t a library you could wander into and borrow from. It was a reference library, a place to consult books on site. Think of it as a very grand reading room.'},{title:'The round arches',start:35.6,text:'Follow the rows of round-topped windows across the second and third floors. Look at the windows: every one is topped with a round arch. That’s Rundbogenstil, the German round-arch style you might remember from the Puck Building. It’s the same family of design, built about 30 years earlier. The bottom floor is rough-cut brownstone, a heavy base. Above it, brick walls are framed by brownstone trim, and the roofline has a decorated cornice and a parapet topped with urns.'},{title:'Three buildings in one',start:67.84,text:'Scan across the whole façade and see if you can find where one section ends and the next begins. You’re really looking at three buildings in one. Alexander Saeltzer designed the original in the 1850s. As the library grew, a central section was added in the late 1850s by Griffith Thomas, and a third section in the early 1880s by Thomas Stent. Both followed Saeltzer’s design so closely that the façade reads as a single piece. If you can’t find the seams, that’s the point.'},{title:'From library to refuge',start:101.36,text:'Look at the main entrance and the stoop. The library moved out in 1911, when the New York Public Library’s main branch opened on Fifth Avenue. The building then sat empty for years, until the Hebrew Immigrant Aid Society bought it at the end of 1919. From 1921 until 1965, it served as an aid center for Jewish immigrants and refugees—a place of shelter, meals, and help finding a way forward. Think of how many people crossed these doors at the start of a new life.'},{title:'The rescue',start:135.92,text:'Look up at the roofline and cornice, the part that nearly came down. By the mid-1960s, the building was worn out and faced demolition. A developer wanted to replace it with an apartment block. Instead, the city landmarked it in 1965, and Joseph Papp, who ran the New York Shakespeare Festival, saw its future as a year-round home for theater. The Public Theater opened here in 1967. Its first big production was the musical Hair, and the architecture critic Ada Louise Huxtable reportedly called the building’s survival a miracle.'},{title:'Today',start:172.82,text:'Step toward the entrance and look up at the glass canopy and lighting. A major renovation reopened in 2012. The architects, Ennead, reshaped the entrance with a new stoop and a glass canopy, and the artist Ben Rubin installed the Shakespeare Machine, a light fixture made of LED screens that flash fragments of Shakespeare’s plays. Inside, the building also holds Joe’s Pub, a music and cabaret venue that opened in 1998. A library, a refuge, and a theater, all behind the same round arches. So when you pass this block, look up at the arches. They’ve framed readers, refugees, and actors, and each time the building has found a new way to belong to the city.'}]},
        teaser:'Before Broadway, Hamilton happened here.',hook:'Library first. Theater next. Hamilton after that.',
    story:'This red-brick and brownstone building opened in 1854 as the Astor Library, New York’s first free public library, built with John Jacob Astor’s fortune. Its collections later helped found the New York Public Library. In the 1960s, producer Joseph Papp saved the empty building and turned it into the Public Theater. Hair opened here in 1967, A Chorus Line in 1975, and Hamilton had its world premiere here in 2015 before moving to Broadway.',
    looks:['Stand across Lafayette Street to see the long arched façade, built in three stages.','Notice the round-arched windows that once lit the library’s reading rooms.','Look for the Public’s bold signs set against the old library walls: then and now in one view.'],
    culture:[{type:'On stage · world premiere',title:'Hamilton (2015)',text:'Lin-Manuel Miranda’s musical premiered here at the Public before transferring to Broadway later that year.'}],
    tip:'The lobby is open around performances. Tickets and the free Shakespeare in the Park lottery are on the Public’s website.',
    sources:[['The Public Theater','https://publictheater.org/'],['Public Theater · Wikipedia','https://en.wikipedia.org/wiki/Public_Theater']]
  }
];
